  const vaFeeOi=feePerOi(fees30,va),liFeeOi=feePerOi(li.fees30,{oi:li.oi}),extFeeOi=feePerOi(extFees30,ext);
  $('#cmpSignalEfficiency')&&($('#cmpSignalEfficiency').textContent=pct(vaFeeOi)+' fee / OI');
