function renderBiweeklyResearch(){
  const host=$('#bwResearchGrid'); if(!host)return;
  const H=BIWEEKLY_HISTORY, finite=v=>Number.isFinite(v), nfmt=(v,unit='')=>{
    if(!finite(v))return '—'; const a=Math.abs(v), sign=v<0?'-':'';
    if(unit==='%')return (v>=0?'+':'')+v.toFixed(1)+'%';
    if(a>=1e9)return sign+'$'+(a/1e9).toFixed(1)+'B';
    if(a>=1e6)return sign+'$'+(a/1e6).toFixed(2)+'M';
    if(a>=1e3)return sign+(a/1e3).toFixed(1)+'K'; return v.toFixed(2);
  };
  const pct=(a,b)=>finite(a)&&finite(b)&&a!==0?(b/a-1)*100:null;
  const series=k=>H.map((r,i)=>({i,d:r.asOf,v:r[k],r})).filter(x=>finite(x.v));
  const changeSeries=k=>{const s=series(k);return s.slice(1).map((x,i)=>pct(s[i].v,x.v)).filter(finite)};
  const sd=a=>{if(!a.length)return 0;const m=a.reduce((s,v)=>s+v,0)/a.length;return Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/a.length)};
  const corr=(a,b)=>{const rows=H.filter(r=>finite(r[a])&&finite(r[b]));if(rows.length<3)return null;const av=rows.reduce((s,r)=>s+r[a],0)/rows.length,bv=rows.reduce((s,r)=>s+r[b],0)/rows.length;let top=0,aa=0,bb=0;rows.forEach(r=>{const x=r[a]-av,y=r[b]-bv;top+=x*y;aa+=x*x;bb+=y*y});return top/Math.sqrt(aa*bb)};
  const turnover=H.map((r,i)=>i&&finite(r.totalVolume)&&finite(H[i-1].totalVolume)&&finite(r.oi)?{i,d:r.asOf,v:(r.totalVolume-H[i-1].totalVolume)/r.oi,r}:null).filter(Boolean);
  const leverage=H.map((r,i)=>finite(r.oi)&&finite(r.tvl)?{i,d:r.asOf,v:r.oi/r.tvl,r}:null).filter(Boolean);
  const pnl=series('netProfit2w'), costs=H.map((r,i)=>finite(r.spreads2w)&&finite(r.mmCosts2w)&&finite(r.netProfit2w)?{i,d:r.asOf,c:r.mmCosts2w/r.spreads2w*100,p:r.netProfit2w/r.spreads2w*100,r}:null).filter(Boolean);
  const esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
  const frame=(num,title,sub,body,wide=false,note='')=>`<article class="bw-viz${wide?' wide':''}"><div class="bw-viz-kicker"><span>${String(num).padStart(2,'0')}</span><span>official reports · n=${H.length}</span></div><h3>${title}</h3><p class="bw-viz-sub">${sub}</p>${body}${note?`<div class="bw-viz-note">${note}</div>`:''}</article>`;
  const line=(sets,{w=620,h=245,min=null,max=null,labels=true,area=false}={})=>{
    const all=sets.flatMap(s=>s.pts.map(p=>p.v)).filter(finite), lo=min??Math.min(...all),hi=max??Math.max(...all),span=hi-lo||1,P={l:48,r:18,t:15,b:32};
    const indices=sets.flatMap(s=>s.pts.map((p,i)=>finite(p.i)?p.i:i)),xMin=Math.min(...indices),xMax=Math.max(...indices),x=i=>P.l+(w-P.l-P.r)*((i-xMin)/(xMax-xMin||1)),y=v=>P.t+(h-P.t-P.b)*(1-(v-lo)/span);
    const grids=[0,.25,.5,.75,1].map(t=>`<line class="grid" x1="${P.l}" y1="${y(lo+span*t)}" x2="${w-P.r}" y2="${y(lo+span*t)}"/><text class="axis" x="${P.l-7}" y="${y(lo+span*t)+3}" text-anchor="end">${esc(nfmt(lo+span*t))}</text>`).join('');
    const paths=sets.map((s,si)=>{const xi=(p,i)=>x(finite(p.i)?p.i:i),d=s.pts.map((p,i)=>(i?'L':'M')+xi(p,i)+' '+y(p.v)).join(' '),cls='series-'+String.fromCharCode(97+si),dots=s.pts.map((p,i)=>`<circle class="dot-${String.fromCharCode(97+si)}" cx="${xi(p,i)}" cy="${y(p.v)}" r="2.6"><title>${p.d} · ${nfmt(p.v)}</title></circle>`).join('');return `${area?`<path d="${d}L${xi(s.pts.at(-1),s.pts.length-1)} ${h-P.b}L${xi(s.pts[0],0)} ${h-P.b}Z" fill="var(--cyan)" opacity=".08"/>`:''}<path class="${cls}" d="${d}"/>${dots}`}).join('');
    const first=sets[0].pts[0]?.d?.slice(2,7)||'',last=sets[0].pts.at(-1)?.d?.slice(2,7)||'';
    return `<svg viewBox="0 0 ${w} ${h}" role="img">${grids}${paths}${labels?`<text class="axis" x="${P.l}" y="${h-8}">${first}</text><text class="axis" x="${w-P.r}" y="${h-8}" text-anchor="end">${last}</text>`:''}</svg>`;
  };
  const bars=(items,{w=620,h=245,max=null,zero=true}={})=>{const P={l:120,r:55,t:12,b:18},vals=items.map(x=>x.v),hi=max??Math.max(...vals,0),lo=zero?Math.min(0,...vals):Math.min(...vals),span=hi-lo||1,row=(h-P.t-P.b)/items.length,x=v=>P.l+(w-P.l-P.r)*(v-lo)/span,x0=x(0);return `<svg viewBox="0 0 ${w} ${h}" role="img"><line class="grid" x1="${x0}" y1="${P.t}" x2="${x0}" y2="${h-P.b}"/>${items.map((it,i)=>{const yy=P.t+i*row+row*.18,bh=row*.64,xx=Math.min(x0,x(it.v)),ww=Math.abs(x(it.v)-x0),cls=it.cls||'dot-a';return `<text class="axis" x="${P.l-8}" y="${yy+bh*.7}" text-anchor="end">${esc(it.l)}</text><rect class="${cls}" x="${xx}" y="${yy}" width="${Math.max(2,ww)}" height="${bh}" opacity=".86"/><text class="value" x="${Math.max(x0,x(it.v))+6}" y="${yy+bh*.7}">${esc(it.f||nfmt(it.v))}</text>`}).join('')}</svg>`};
  const scatter=(pts,{xk='x',yk='y',w=620,h=245}={})=>{const P={l:48,r:18,t:15,b:32},xs=pts.map(p=>p[xk]),ys=pts.map(p=>p[yk]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),x=v=>P.l+(w-P.l-P.r)*(v-xmin)/(xmax-xmin||1),y=v=>P.t+(h-P.t-P.b)*(1-(v-ymin)/(ymax-ymin||1));return `<svg viewBox="0 0 ${w} ${h}" role="img"><line class="grid" x1="${P.l}" y1="${h-P.b}" x2="${w-P.r}" y2="${h-P.b}"/><line class="grid" x1="${P.l}" y1="${P.t}" x2="${P.l}" y2="${h-P.b}"/>${pts.map(p=>`<circle class="dot-a" cx="${x(p[xk])}" cy="${y(p[yk])}" r="4" opacity=".82"><title>${p.d} · ${p[xk].toFixed(0)} markets · ${nfmt(p[yk])}</title></circle>`).join('')}<text class="axis" x="${P.l}" y="${h-8}">${xmin.toFixed(0)}</text><text class="axis" x="${w-P.r}" y="${h-8}" text-anchor="end">${xmax.toFixed(0)} markets</text><text class="axis" x="${P.l-6}" y="${P.t+3}" text-anchor="end">${nfmt(ymax)}</text></svg>`};
  const growth=['tvl','wau','olpPnlLife','dau','oi','totalVolume'].map((k,i)=>{const s=series(k);return {l:{tvl:'TVL',wau:'WAU',olpPnlLife:'OLP PnL',dau:'DAU',oi:'Open interest',totalVolume:'Volume'}[k],v:pct(s[0]?.v,s.at(-1)?.v),f:nfmt(pct(s[0]?.v,s.at(-1)?.v),'%'),cls:k==='tvl'?'dot-d':'dot-a'}}).filter(x=>finite(x.v));
  const volOi=series('totalVolume').map((p,i)=>({...p,v:p.v/1e9})), oi=series('oi').map(p=>({...p,v:p.v/1e6}));
  const volMarkets=H.filter(r=>finite(r.markets)&&finite(r.totalVolume)).map(r=>({x:r.markets,y:r.totalVolume,d:r.asOf}));
  const dau=series('dau'),wau=series('wau'),life=series('olpPnlLife');
  const volat=[['Net Profit','netProfit2w'],['OI','oi'],['DAU','dau'],['WAU','wau'],['Treasury','treasuryHoldings'],['Volume','totalVolume'],['TVL','tvl'],['OLP PnL','olpPnlLife'],['Markets','markets']].map(([l,k],i)=>({l,v:sd(changeSeries(k)),f:sd(changeSeries(k)).toFixed(1)+' pp',cls:i===0?'dot-d':'dot-a'})).sort((a,b)=>b.v-a.v);
  const lastSix=H.filter(r=>finite(r.spreads2w)&&finite(r.mmCosts2w)&&finite(r.netProfit2w)).slice(-6);
  const grouped=`<svg viewBox="0 0 620 245" role="img">${lastSix.map((r,i)=>{const mx=Math.max(...lastSix.flatMap(x=>[x.spreads2w,x.mmCosts2w,x.netProfit2w])),base=212,scale=180/mx,x=55+i*91;return `<rect class="dot-a" x="${x}" y="${base-r.spreads2w*scale}" width="17" height="${r.spreads2w*scale}" opacity=".82"/><rect class="dot-d" x="${x+19}" y="${base-r.mmCosts2w*scale}" width="17" height="${r.mmCosts2w*scale}" opacity=".82"/><rect class="dot-c" x="${x+38}" y="${base-r.netProfit2w*scale}" width="17" height="${r.netProfit2w*scale}" opacity=".82"/><text class="axis" x="${x+27}" y="230" text-anchor="middle">${r.asOf.slice(5)}</text>`}).join('')}<line class="grid" x1="45" y1="212" x2="605" y2="212"/></svg>`;
  const may=H.map((r,i)=>({i,d:r.asOf,markets:r.markets,dau:r.dau,profit:r.netProfit2w}));
  const minP=pnl.reduce((a,b)=>a.v<b.v?a:b),maxP=pnl.reduce((a,b)=>a.v>b.v?a:b),latestP=pnl.at(-1);
  const correlations=[['Volume × markets',corr('totalVolume','markets')],['Volume × OI',corr('totalVolume','oi')],['Volume × DAU',corr('totalVolume','dau')],['DAU × WAU',corr('dau','wau')]].map(([l,v],i)=>({l,v,f:v.toFixed(2),cls:i===3?'dot-c':i===0?'dot-d':'dot-b'}));
  const recentTurn=turnover.slice(-5), nextLabel=recentTurn.length?recentTurn.at(-1).v.toFixed(1):'—',turnRebounded=recentTurn.length>1&&recentTurn.at(-1).v>recentTurn.at(-2).v;
  host.innerHTML=
    frame(1,'Long-run growth by metric','Change from the first comparable disclosure to the latest report.',bars(growth,{max:Math.max(600,...growth.map(x=>x.v))}),false,'<b>TVL is the weakest long-run growth metric.</b> Every series uses its own first disclosed value, so starting dates can differ.')+
    frame(2,'Market-making cost and net profit margin','Share of gross spreads for every report with full P&L disclosure.',`<div class="bw-viz-legend"><span><i class="d"></i>MM cost</span><span><i class="c"></i>Net profit margin</span></div>${line([{pts:costs.map(x=>({v:x.c,d:x.d}))},{pts:costs.map(x=>({v:x.p,d:x.d}))}],{min:0,max:100})}`,false,'The mirror-like movement shows that <b>cost, not gross revenue, drives profit volatility.</b>')+
    frame(3,'Net profit by two-week report','Contribution margin after disclosed market-making costs and rewards.',line([{pts:pnl}],{min:0,area:true}),false,`Peak ${nfmt(maxP.v)}, trough ${nfmt(minP.v)}, latest ${nfmt(latestP.v)}.`)+
    frame(4,'Volume-to-OI turnover','Incremental two-week volume divided by reported open interest.',line([{pts:turnover}],{min:0}),false,'Lower turnover means more open exposure sits behind each dollar of new trading volume.')+
    frame(5,'Cumulative volume and open interest','Cumulative volume in $B and OI in $M, indexed to their own axes.',`<div class="bw-viz-legend"><span><i></i>Cumulative volume</span><span><i class="b"></i>Open interest</span></div>${line([{pts:volOi},{pts:oi}],{min:0})}`,true,'Both grew strongly, but OI moved through larger cycles while cumulative volume advanced continuously.')+
    frame(6,'Cumulative volume vs listed markets','Each point is one official report at a shared biweekly grain.',scatter(volMarkets),false,'The point cloud does not support a simple “more listings equals more volume” relationship.')+
    frame(7,'Daily and weekly active users','DAU and WAU move together across the complete reporting history.',`<div class="bw-viz-legend"><span><i class="c"></i>DAU</span><span><i class="d"></i>WAU</span></div>${line([{pts:dau},{pts:wau}],{min:0})}`,false,`Pearson r = <b>${corr('dau','wau').toFixed(2)}</b>. The strong relationship is consistent with repeat usage, though correlation alone does not prove retention.`)+
    frame(8,'Lifetime OLP PnL','Cumulative liquidity-provider PnL disclosed in official reports.',line([{pts:life}],{min:0,area:true}),false,`${nfmt(pct(life[0].v,life.at(-1).v),'%')} since the first report, with only ${life.slice(1).filter((p,i)=>p.v<life[i].v).length} declining periods.`)+
    frame(9,'Implied leverage over time','Open interest divided by TVL. TVL excludes some hedging accounts.',line([{pts:leverage}],{min:0}),true,`Range: <b>${Math.min(...leverage.map(x=>x.v)).toFixed(2)}x-${Math.max(...leverage.map(x=>x.v)).toFixed(2)}x</b>. It cycled rather than rising without interruption.`)+
    frame(10,'How to read implied leverage','Trading exposure per $1 of reported deposited capital.',`<div class="bw-formula"><div class="oi"><b>Open interest</b><span>trading exposure</span></div><b>÷</b><div class="tvl"><b>TVL</b><span>reported deposited capital</span></div></div>${line([{pts:leverage}],{min:0,h:165})}`,false,'The riskier pattern would be a persistent climb. The observed series falls, ranges, and later recovers.')+
    frame(11,'Volatility of report-over-report changes','Standard deviation of percentage changes, measured in percentage points.',bars(volat,{max:Math.max(...volat.map(x=>x.v))*1.12}),false,'Net profit is the most volatile disclosed metric by a wide margin.')+
    frame(12,'Gross spreads, market-making cost, and net profit','Latest six reports with complete, directly comparable P&L fields.',`<div class="bw-viz-legend"><span><i></i>Gross spreads</span><span><i class="d"></i>MM cost</span><span><i class="c"></i>Net profit</span></div>${grouped}`,true,'These are contribution-margin components. They do not include every corporate operating expense.')+
    frame(13,'Recent turnover close-up','The latest five completed volume-to-OI observations.',line([{pts:recentTurn}],{min:0,h:190}),false,`Latest: <b>${nextLabel}x</b>. ${turnRebounded?'The fifth checkpoint rebounded, breaking the prior four-report decline.':'Another sequential decline would strengthen the case for a structural efficiency trend.'}`)+
    frame(14,'The May 2026 joint slowdown','Listed markets, DAU, and net profit are normalized within each series so timing can be compared.',`<div class="bw-viz-legend"><span><i></i>Markets</span><span><i class="c"></i>DAU</span><span><i class="b"></i>Net profit</span></div>${line(['markets','dau','profit'].map((k)=>{const pts=may.filter(x=>finite(x[k])),lo=Math.min(...pts.map(x=>x[k])),hi=Math.max(...pts.map(x=>x[k]));return {pts:pts.map(x=>({i:x.i,d:x.d,v:(x[k]-lo)/(hi-lo||1)*100}))}}),{min:0,max:100})}`,true,'The synchronized dip suggests a broader protocol activity slowdown, not an isolated profitability event.')+
    frame(15,'Net profit: peak, trough, and latest','Annotated landmarks from the directly comparable P&L era.',line([{pts:pnl}],{min:0}),false,`Peak <b>${maxP.d}: ${nfmt(maxP.v)}</b>. Trough <b>${minP.d}: ${nfmt(minP.v)}</b>. Latest <b>${latestP.d}: ${nfmt(latestP.v)}</b>.`)+
    frame(16,'What moves together','Pearson correlation across matched official-report observations.',bars(correlations,{max:1}),false,'Volume and listed markets have the weakest relationship. DAU and WAU have the strongest.')+
    frame(17,'What to watch: MM cost share','Current disclosed range and the two interpretation paths.',`<div class="bw-watch"><div class="source">MM cost has ranged ${Math.min(...costs.map(x=>x.c)).toFixed(0)}%-${Math.max(...costs.map(x=>x.c)).toFixed(0)}% of gross spreads</div><div class="good"><b>Narrows</b><span>Net profit volatility likely resolves</span></div><div class="arrow">→</div><div class="risk"><b>Stays erratic</b><span>Profit keeps swinging regardless of volume</span></div></div>`,false,'This is the highest-priority cost-quality monitor.')+
    frame(18,'What to watch: volume-to-OI turnover',turnRebounded?'The fifth checkpoint rebounded after four consecutive declines.':'A fifth straight decline would require a deeper operational explanation.',`${line([{pts:recentTurn}],{min:0,h:165})}<div class="bw-watch"><div class="source">Latest checkpoint: ${nextLabel}x ${turnRebounded?'and the decline streak broke':'with the decline still active'}</div><div class="good"><b>${turnRebounded?'Rebounded':'Stabilizes'}</b><span>${turnRebounded?'Current evidence favors a cyclical slowdown':'Recent decline may be cyclical'}</span></div><div class="arrow">→</div><div class="risk"><b>Watch next</b><span>A renewed decline would reopen the efficiency question</span></div></div>`,false,'Volume is calculated from the change in cumulative volume between reports; OI is the ending snapshot for each window.');
}
function renderBiweekly(){
  if(!$('#bwBlock'))return;
  const B=BIWEEKLY, M=v=>Number.isFinite(v)?'$'+(v>=1e9?(v/1e9).toFixed(2)+'B':v>=1e6?(v/1e6).toFixed(2)+'M':fmtK(v)):'—';
  const fmtMetric=(d,v)=>!Number.isFinite(v)?'—':d.t==='int'?Math.round(v).toLocaleString():d.t==='pct'?v.toFixed(2)+'%':M(v);
  const pctChange=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&a!==0?(b/a-1)*100:null;
  const signed=p=>p==null?'—':(p>=0?'+':'')+p.toFixed(1)+'%';
  const pointsFor=k=>BIWEEKLY_HISTORY.map((r,i)=>({r,i,v:r[k]})).filter(x=>Number.isFinite(x.v));
  const spark=pts=>{
    if(pts.length<2)return '';
    const W=170,H=34,P=2, vals=pts.map(x=>x.v), lo=Math.min(...vals), hi=Math.max(...vals), span=hi-lo||1;
    const xy=vals.map((v,i)=>[P+(W-P*2)*(i/(vals.length-1)),H-P-(H-P*2)*((v-lo)/span)]);
    const path=xy.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' '), end=xy[xy.length-1];
    return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><path d="${path}" fill="none" stroke="var(--cyan)" stroke-width="2" vector-effect="non-scaling-stroke"/><circle cx="${end[0]}" cy="${end[1]}" r="2.5" fill="var(--grn)"/></svg>`;
  };
  const datedSpark=(pts,d)=>{
    if(pts.length<2)return '<span class="muted">Only one official report</span>';
    const W=720,H=86,PX=12,top=25,bottom=9,vals=pts.map(x=>x.v),lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1;
    const xy=vals.map((v,i)=>[PX+(W-PX*2)*(i/(vals.length-1)),H-bottom-(H-top-bottom)*((v-lo)/span)]);
    const path=xy.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
    const dots=xy.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${i===xy.length-1?4:2.5}" fill="${i===xy.length-1?'var(--grn)':'var(--cyan)'}"><title>${pts[i].r.asOf} · ${fmtMetric(d,pts[i].v)}</title></circle>`).join('');
    const labels=xy.map((p,i)=>{const y=Math.max(10,p[1]-7-(i%2)*7);return `<text class="bw-point-value" x="${p[0]}" y="${y}" text-anchor="start" transform="rotate(-32 ${p[0]} ${y})">${fmtMetric(d,pts[i].v)}</text>`}).join('');
    const mid=pts[Math.floor((pts.length-1)/2)];
    return `<div class="bw-metric-trend"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${d.l} by official report date"><path d="${path}" fill="none" stroke="var(--cyan)" stroke-width="2.5" vector-effect="non-scaling-stroke"/>${dots}${labels}</svg><div class="bw-metric-dates"><span>${pts[0].r.asOf}</span><span>${mid.r.asOf}</span><span>${pts[pts.length-1].r.asOf}</span></div></div>`;
  };
  $('#bwAsOf').textContent='2-week window · posted '+B.asOf;
  if($('#bwProduct')){
    const updates=Array.isArray(B.product)?B.product:[];
    $('#bwProduct').innerHTML=updates.length?`<div class="bw-product-release"><span>Latest product release</span><strong>${escapeHTML(B.release||'Latest')}</strong><small>${escapeHTML(B.asOf)}</small></div><div class="bw-product-items">${updates.map((item,index)=>`<div><span>0${index+1}</span><b>${escapeHTML(item)}</b></div>`).join('')}</div>`:'';
    $('#bwProduct').hidden=!updates.length;
  }
  const margin=B.netProfit2w/B.spreads2w*100;
  const M0=v=>'$'+(v>=1e6?(v/1e6).toFixed(2)+'M':fmtK(v));
  $('#bwTeaser') && ($('#bwTeaser').textContent=M0(B.netProfit2w)+' / 2w');
  $('#bwPnl').innerHTML=
    `<div class="step"><span>1 · Money paid by traders</span><b>${M(B.spreads2w)}</b><small>spread payments during these 2 weeks</small></div>`+
    `<div class="step neg"><span>2 · Cost to run the market</span><b>-${M(B.mmCosts2w)}</b><small>market-making cost</small></div>`+
    `<div class="step"><span>3 · Money after market cost</span><b>${M(B.netRevenue2w)}</b><small>corrected net revenue${B.netRevenue2wOriginal?` · originally ${M(B.netRevenue2wOriginal)}`:''}</small></div>`+
    `<div class="step neg"><span>4 · Rewards paid to users</span><b>-${M(B.rewards2w)}</b><small>includes referral rewards</small></div>`+
    `<div class="step pos"><span>5 · Final money left over</span><b>${M(B.netProfit2w)}</b><small>net profit · ${margin.toFixed(0)} cents kept per $1 of spread payments</small></div>`;
  $('#bwGrid').innerHTML=[
    ['TVL (ex-hedging)',M(B.tvl)],['Dual-sided OI',M(B.oi)],['Total volume traded',M(B.totalVolume)],
    ['Markets listed',B.markets.toLocaleString()],['DAU (7d avg)',Number.isFinite(B.dau)?B.dau.toLocaleString():'Not published'],['WAU',Number.isFinite(B.wau)?B.wau.toLocaleString():'Not published'],
    ['2w treasury inflow',M(B.treasury2w)],['2w OLP PnL',M(B.olpPnl2w)],['Lifetime OLP PnL',M(B.olpPnlLife)],
    ['Treasury holdings',M(B.treasuryHoldings)],['Rewards claimed · life',M(B.rewardsClaimed)],['Losses refunded · Sunset',M(B.lossesRefunded)]
  ].map(([k,v])=>`<div class="t">${k}<b>${v}</b></div>`).join('');
  /* long-run direction + latest report-over-report core scorecard */
  const H=BIWEEKLY_HISTORY, prev=H.length>1?H[H.length-2]:null;
  const core=BW_CORE_KEYS.map(k=>{
    const d=BW_METRIC_DEFS.find(x=>x.k===k), pts=pointsFor(k), first=pts[0], last=pts[pts.length-1], prior=pts[pts.length-2];
    return {d,pts,first,last,prior,long:first&&last?pctChange(first.v,last.v):null,recent:prior&&last?pctChange(prior.v,last.v):null};
  }).filter(x=>x.last&&x.last.r===B);
  const longUp=core.filter(x=>x.long>0).length, recentUp=core.filter(x=>x.recent>0).length;
  const recentDown=core.filter(x=>x.recent<0).map(x=>x.d.l.replace(/ ·.*/,''));
  const volumeCore=core.find(x=>x.d.k==='totalVolume'), profitCore=core.find(x=>x.d.k==='netProfit2w');
  if($('#bwVerdict'))$('#bwVerdict').innerHTML=
    `<div class="bw-verdict-score"><span>Long-run direction check</span><strong>${longUp}/${core.length}</strong><b>core metrics are above their first comparable official report</b></div>`+
    `<div class="bw-verdict-copy"><div><span>Exchange scale</span><b>${signed(volumeCore?.long)}</b><small>Total volume since ${volumeCore?.first?.r.asOf||'first report'}</small></div>`+
    `<div><span>Latest pulse</span><b>${recentUp}/${core.length} rose</b><small>vs ${prev?.asOf||'previous report'}</small></div>`+
    `<div><span>Current watchlist</span><b>${recentDown.length?recentDown.join(' · '):'No core declines'}</b><small>${recentDown.length?'fell in the latest official report':'all core metrics increased'}</small></div></div>`;
  if($('#bwDeltas')){
    $('#bwDeltas').innerHTML=core.map(x=>`<div class="d ${x.long>=0?'up':'dn'}"><span>${x.d.l}</span><b>${fmtMetric(x.d,x.last.v)}</b>`+
      `<div class="delta-line"><em>since ${x.first.r.asOf}</em><i class="${x.long>=0?'up':'dn'}">${signed(x.long)}</i></div>`+
      `<div class="delta-line"><em>vs ${x.prior?.r.asOf||'prior'}</em><i class="${x.recent>=0?'up':'dn'}">${signed(x.recent)}</i></div>${spark(x.pts).replace('<svg','<svg class="bw-mini"')}</div>`).join('');
  }
  renderBiweeklyResearch();
  /* on-chain progress available today: treasury inflow per trailing 14-day window */
  if($('#bwTrend')&&typeof cumAt==='function'&&Array.isArray(SERIES)&&SERIES.length){
    const lastD=SERIES[SERIES.length-1].d;
    const wins=[];
    for(let k=5;k>=0;k--){
      const end=addDays(lastD,-14*k), start=addDays(end,-14);
      wins.push({end,v:Math.max(0,cumAt(end)-cumAt(start))});
    }
    const mx=Math.max(...wins.map(w=>w.v))||1;
    const cur=wins[wins.length-1].v, prv=wins[wins.length-2]?wins[wins.length-2].v:0;
    const g=prv>0?(cur/prv-1)*100:0;
    const first=wins[0].v, tot=first>0?(cur/first-1)*100:0;
    $('#bwTrend').innerHTML=
      `<div class="bw-trend-head"><span>Each bar is real USDC added to the protocol treasury during one completed 14-day window.</span><span class="bw-trend-stat"><b class="${g>=0?'up':'dn'}">${g>=0?'+':''}${g.toFixed(1)}%</b><small>vs previous 14 days</small></span><span class="bw-trend-stat"><b class="${tot>=0?'up':'dn'}">${tot>=0?'+':''}${tot.toFixed(0)}%</b><small>vs 12 weeks ago</small></span></div>`+
      `<div class="bw-bars">${wins.map((w,i)=>`<div class="bar${i===wins.length-1?' cur':''}" title="14d ending ${w.end} · $${fmtK(w.v)}"><i>$${fmtK(w.v)}</i><span style="display:block;height:${Math.max(6,w.v/mx*96)}px"></span></div>`).join('')}</div>`+
      `<div class="bw-trend-cap">${wins.map(w=>`<span>${w.end.slice(5)}</span>`).join('')}</div>`;
  }
  /* stored report history */
  if($('#bwHist')){
    const histDelta=(r,k)=>{
      const at=H.indexOf(r),now=r[k]; if(!Number.isFinite(now))return null;
      for(let i=at-1;i>=0;i--)if(Number.isFinite(H[i][k]))return pctChange(H[i][k],now);
      return null;
    };
    const histCell=(r,k,d)=>{
      const v=r[k],p=histDelta(r,k);
      return `<span><b>${fmtMetric(d,v)}</b><small class="${p==null?'':p>=0?'up':'dn'}">${p==null?'not previously comparable':signed(p)+' vs prior'}</small></span>`;
    };
    const defs=Object.fromEntries(BW_METRIC_DEFS.map(d=>[d.k,d]));
    $('#bwHist').innerHTML=H.length>1?
      `<div class="hrow h"><span>Report date · accounting style</span><span>All trading ever</span><span>Money in open trades</span><span>Money deposited (TVL)</span><span>Daily users</span><span>Weekly users</span><span>Money before costs · 2w</span><span>Money after market cost</span><span>Final money left</span><span>Real USDC held</span></div>`+
      H.slice().reverse().map(r=>{
        const pnl=Number.isFinite(r.spreads2w), early=r.reportFormat==='early-revenue-allocation';
        const model=pnl?'Spreads P&amp;L':r.reportFormat==='net-revenue-allocation'?'Net revenue allocation':early?'Early revenue allocation':'Revenue allocation';
        const top=pnl?r.spreads2w:Number.isFinite(r.revenue2w)?r.revenue2w:r.netRevenue2w;
        const topKey=pnl?'spreads2w':Number.isFinite(r.revenue2w)?'revenue2w':'netRevenue2w';
        return `<div class="hrow"><span><b>${r.asOf}</b><i class="era${early?' early':''}">${model}</i></span>`+
          histCell(r,'totalVolume',defs.totalVolume)+histCell(r,'oi',defs.oi)+histCell(r,'tvl',defs.tvl)+
          histCell(r,'dau',defs.dau)+histCell(r,'wau',defs.wau)+histCell(r,topKey,defs[topKey])+ 
          histCell(r,'netRevenue2w',defs.netRevenue2w)+histCell(r,'netProfit2w',defs.netProfit2w)+histCell(r,'treasuryHoldings',defs.treasuryHoldings)+`</div>`;
      }).join('')+
      `<div class="bw-hist-note"><b>Definition break:</b> early “2w Revenue” allocation reports are not the same disclosure as later gross spreads → market-making costs → net profit reports. Dashes mean the metric was not published, not zero.</div>`
      :'<div class="bw-hist-empty">One official report is stored. The table appears as soon as a second dated report is appended; no synthetic history is generated.</div>';
  }
  /* every published metric as a definition-safe atlas */
  if($('#bwMetricAtlas')){
    const groups=[...new Set(BW_METRIC_DEFS.map(d=>d.g))];
    $('#bwMetricAtlas').innerHTML=`<div class="bw-atlas-axis"><span></span><span>Metric</span><span>Latest</span><span class="trend-axis"><i>${H[0].asOf}</i><i>Official report timeline</i><i>${H[H.length-1].asOf}</i></span><span>Since first</span><span>Vs previous</span></div>`+groups.map(g=>{
      const rows=BW_METRIC_DEFS.filter(d=>d.g===g).map(d=>{
        const pts=pointsFor(d.k); if(!pts.length)return '';
        const first=pts[0],last=pts[pts.length-1],prior=pts[pts.length-2];
        const long=pctChange(first.v,last.v), recent=prior?pctChange(prior.v,last.v):null;
        return `<div class="bw-metric-row"><span class="name">${d.l}</span><b class="latest">${fmtMetric(d,last.v)}</b>${datedSpark(pts,d)}`+
          `<span class="change ${long==null?'na':long>=0?'up':'dn'}">${signed(long)}<small>since ${first.r.asOf}</small></span>`+
          `<span class="change ${recent==null?'na':recent>=0?'up':'dn'}">${signed(recent)}<small>${prior?'vs '+prior.r.asOf:pts.length+' report'}</small></span></div>`;
      }).join('');
      return rows?`<section class="bw-atlas-group"><h3>${g}</h3><div class="bw-atlas-rows">${rows}</div></section>`:'';
    }).join('');
  }
  /* complete original report explorer, including exceptions and definition changes */
  const reportSelect=$('#bwReportSelect'), reportDetail=$('#bwReportDetail');
  if(reportSelect&&reportDetail){
    const keep=reportSelect.value||B.asOf;
    reportSelect.innerHTML=H.slice().reverse().map(r=>`<option value="${r.asOf}">${r.asOf} · ${r.reportFormat||'spreads-pnl'}</option>`).join('');
    reportSelect.value=H.some(r=>r.asOf===keep)?keep:B.asOf;
    const paintReport=date=>{
      const r=H.find(x=>x.asOf===date)||B;
      const values=BW_METRIC_DEFS.filter(d=>Number.isFinite(r[d.k])).map(d=>{
        const label=d.k==='markets'?(r.listingMetric==='tokens'?'Tokens listed':'Markets listed'):d.l;
        return `<div class="bw-report-value"><span>${label}</span><b>${fmtMetric(d,r[d.k])}</b></div>`;
      }).join('');
      const notes=[];
      notes.push(`Disclosure model: ${r.reportFormat||'spreads-pnl'}`);
      if(r.reportEra)notes.push(r.reportEra);
      if(r.tvlScope)notes.push(`TVL scope: ${r.tvlScope}`);
      if(r.treasuryStatus)notes.push(`Treasury: ${r.treasuryStatus}`);
      if(r.referralRewardsStatus)notes.push(`Referral rewards: ${r.referralRewardsStatus}`);
      if(r.correctionNote)notes.push(`Official correction: ${r.correctionNote}`);
      const alloc=['olpAllocation2w','lossRefundPool2w','referralRewardsPool2w','treasury2w'].filter(k=>Number.isFinite(r[k])).reduce((s,k)=>s+r[k],0);
      if(Number.isFinite(r.revenue2w)&&alloc)notes.push(`Allocation check: ${M(alloc)} of ${M(r.revenue2w)} (${Math.abs(alloc-r.revenue2w)<1?'reconciled':'definition differs'})`);
      reportDetail.innerHTML=values+`<div class="bw-report-notes"><b>Read before comparing:</b> ${notes.join(' · ')}. Dashes and omitted fields mean not published, never zero.</div>`;
    };
    paintReport(reportSelect.value);
    reportSelect.onchange=()=>paintReport(reportSelect.value);
  }
  const share=B.treasury2w/B.spreads2w*100;
  const netTreasuryShare=B.netProfit2w?B.treasury2w/B.netProfit2w*100:0;
  $('#bwNote').innerHTML=`<b>Do not mix the two percentages:</b> In this official window, traders paid ${M(B.spreads2w)} in gross spreads and ${M(B.treasury2w)} reached treasury — <b>${share.toFixed(0)}% of gross spreads</b>. After market-making costs and rewards, ${M(B.netProfit2w)} remained as net profit; treasury was <b>${netTreasuryShare.toFixed(1)}% of net profit</b> and OLP PnL was the rest. Across the latest ${REVENUE_EVIDENCE.reports.length} reports, the aggregate net-profit split is <b>${(REVENUE_EVIDENCE.treasuryNetShare*100).toFixed(1)}% treasury / ${(REVENUE_EVIDENCE.olpNetShare*100).toFixed(1)}% OLP PnL</b>, while treasury remains exactly <b>${(MKT.spreadShare*100).toFixed(0)}% of gross spreads</b>. Source figures are copied from the <a href="${B.src}" target="_blank" rel="noopener">official biweekly posts</a>; the 14-day chart is calculated independently from on-chain treasury history.`;
}
