/* ---------- live refresh with RPC failover + rate-limit protection ---------- */
const RPC_STATE={cooldown:new Map(),lastOk:null,lastQuorum:0};
const BAL_CACHE=new Map();
async function rpcFrom(url,index,method,params){
  const ctrl=new AbortController();
  const timeout=setTimeout(()=>ctrl.abort(),9000);
  try{
    const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({jsonrpc:'2.0',id:`${Date.now()}-${index}`,method,params}),signal:ctrl.signal});
    if(r.status===429){RPC_STATE.cooldown.set(url,Date.now()+60000);throw new Error('rate limited');}
    if(!r.ok)throw new Error('HTTP '+r.status);
    const j=await r.json();
    if(j.error)throw new Error(j.error.message||'RPC error');
    return {url,result:j.result};
  }catch(err){
    if(err.name==='AbortError')RPC_STATE.cooldown.set(url,Date.now()+15000);
    throw err;
  }finally{clearTimeout(timeout);}
}
function canonicalRpcResult(result){
  if(typeof result==='string'&&/^0x[0-9a-f]+$/i.test(result)){
    try{return '0x'+BigInt(result).toString(16);}catch(_){ }
  }
  return JSON.stringify(result);
}
async function rpc(method,params){
  const active=(CHAIN.rpcs||[]).filter(url=>(RPC_STATE.cooldown.get(url)||0)<=Date.now());
  if(active.length<2)throw new Error('fewer than two RPC providers are available');
  const settled=await Promise.allSettled(active.map((url,index)=>rpcFrom(url,index,method,params)));
  const valid=settled.filter(x=>x.status==='fulfilled').map(x=>x.value);
  const groups=new Map();
  valid.forEach(item=>{
    const key=canonicalRpcResult(item.result);
    if(!groups.has(key))groups.set(key,[]);
    groups.get(key).push(item);
  });
  const match=[...groups.values()].sort((a,b)=>b.length-a.length)[0]||[];
  if(match.length<2)throw new Error('RPC quorum failed: providers returned different results');
  RPC_STATE.lastQuorum=match.length;
  RPC_STATE.lastOk=match.map(x=>new URL(x.url).hostname).join(' + ');
  return match[0].result;
}
async function rpcSingle(url,method,params){
  return (await rpcFrom(url,-1,method,params)).result;
}
async function cachedBalance(pad,block='latest'){
  const tag=typeof block==='number'?'0x'+block.toString(16):block;
  const key=pad+':'+tag, hit=BAL_CACHE.get(key);
  const ttl=tag==='latest'?12000:Infinity;
  if(hit&&Date.now()-hit.at<ttl)return hit.v;
  // Most public Arbitrum endpoints prune historical state. Use the archive
  // endpoint for fixed blocks and retain quorum reads for the live balance.
  const params=[{to:CHAIN.usdc,data:'0x70a08231'+pad},tag];
  const r=tag==='latest'?await rpc('eth_call',params):await rpcSingle(CHAIN.archiveRpc,'eth_call',params);
  const v=parseInt(r,16)/1e6;
  if(!Number.isFinite(v))throw new Error('invalid RPC balance');
  BAL_CACHE.set(key,{v,at:Date.now()});
  return v;
}
async function balAt(block){
  return cachedBalance(CHAIN.pad,block);
}
async function balAtPad(pad,block='latest'){
  return cachedBalance(pad,block);
}
const blockAt=ts=>Math.round(CHAIN.b0+(ts-CHAIN.t0)*CHAIN.bps);
const BLOCK_HEADER_CACHE=new Map();
async function blockHeader(number){
  const hit=BLOCK_HEADER_CACHE.get(number);if(hit)return hit;
  const raw=await rpcSingle(CHAIN.headerRpc,'eth_getBlockByNumber',['0x'+number.toString(16),false]);
  if(!raw)throw new Error('block header unavailable');
  const out={number:parseInt(raw.number,16),timestamp:parseInt(raw.timestamp,16)};
  BLOCK_HEADER_CACHE.set(number,out);return out;
}
async function exactBlockAtTimestamp(ts){
  const latestRaw=await rpcSingle(CHAIN.headerRpc,'eth_getBlockByNumber',['latest',false]);
  if(!latestRaw)throw new Error('latest block header unavailable');
  const latestNumber=parseInt(latestRaw.number,16);
  let guess=Math.min(latestNumber,Math.max(1,blockAt(ts)));
  for(let i=0;i<7;i++){
    const h=await blockHeader(guess),delta=ts-h.timestamp;
    if(Math.abs(delta)<=1)break;
    guess=Math.max(1,guess+Math.round(delta*CHAIN.bps));
  }
  let lo=Math.max(1,guess-64),hi=guess+64,guard=0;
  while((await blockHeader(lo)).timestamp>=ts&&guard++<12){hi=lo;lo=Math.max(1,lo-256*Math.pow(2,guard-1));}
  guard=0;
  while((await blockHeader(hi)).timestamp<ts&&guard++<12){lo=hi;hi+=256*Math.pow(2,guard-1);}
  while(lo+1<hi){
    const mid=Math.floor((lo+hi)/2);
    if((await blockHeader(mid)).timestamp>=ts)hi=mid;else lo=mid;
  }
  return hi;
}
async function balanceAtEtDayEnd(dateStr){
  const closeTs=resetMidnightTs(addDays(dateStr,1));
  return balAt(await exactBlockAtTimestamp(closeTs));
}
async function refresh({deep=false}={}){
  const btn=$('#refresh'),note=$('#note');btn.classList.add('busy');btn.textContent='↻ syncing…';
  $('#stamp').className='';
  try{
    const todayET=resetDateKey();

    // One lightweight request paints the live total first.
    const cur=await balAt('latest');
    LIVE_TOTAL=cur;
    LIVE_BASE={balance:cur,at:performance.now()};
    LIVE_HOUR_BASE={key:resetHourKey(),balance:cur,at:performance.now()};
    $('#totalVal').textContent=fmtUSD(Math.floor(cur));
    renderImpliedSpreadTotal(cur);
    renderActualsFallback(cur);
    const protocolGrowthPromise=refreshProtocolBalanceGrowth();
    tickLive();
    $('#stamp').textContent=`verified ${RPC_STATE.lastQuorum}/${CHAIN.rpcs.length} · ${resetTimeString()} ET`;
    $('#stamp').className='live';
    note.classList.remove('show');

    // Daily history is independent: a rate limit here never downgrades the live total.
    try{
      const closedThrough=addDays(todayET,-1);
      const maxDays=deep?180:32;
      const knownDates=new Set(SERIES.map(x=>x.d));
      const missing=[];
      for(let d=addDays(SERIES[0].d,1);d<=closedThrough&&missing.length<maxDays;d=addDays(d,1)){
        if(!knownDates.has(d))missing.push(d);
      }

      // Historical archive reads are independent. Small concurrent batches fill the
      // calendar much faster without flooding public RPC providers.
      for(let offset=0;offset<missing.length;offset+=6){
        const batch=missing.slice(offset,offset+6);
        const settled=await Promise.allSettled(batch.map(async d=>({d,v:await balanceAtEtDayEnd(d)})));
        const values=settled.filter(x=>x.status==='fulfilled').map(x=>x.value);
        if(!values.length)throw new Error('historical RPC batch unavailable');
        values.forEach(({d,v})=>{
          const i=SERIES.findIndex(x=>x.d===d);
          if(i>=0)SERIES[i].v=v; else SERIES.push({d,v});
        });
        SERIES.sort((a,b)=>a.d<b.d?-1:1);
        persistLiveSeries();
        buildCalendar();
      }
    }catch(_){
      note.classList.remove('show');
      $('#stamp').textContent='live balance · saved daily history';
      $('#stamp').className='warn';
    }
    LIVE_BASE={balance:cur,at:performance.now()};
    LIVE_HOUR_BASE={key:resetHourKey(),balance:cur,at:performance.now()};
    await protocolGrowthPromise;
    if(deep)await renderHourlyEarnings(cur); else renderProjectedHourlyEarnings(cur);
    render();
    renderTwaps();
    if(deep)await renderActuals();
    buildCalendar();
    renderVsLighter();
  }catch(err){
    note.classList.remove('show');
    $('#stamp').textContent='snapshot · '+SERIES[SERIES.length-1].d+' ET';
    $('#stamp').className='warn';
  }finally{btn.classList.remove('busy');btn.textContent='↻ Refresh live';}
}
let quickSyncBusy=false, lastWindowSync=0;
