/* ---------- official roadmap sync ---------- */
let ROADMAP_SYNC_BUSY=false;
function roadmapItemList(items){
  return items.map(item=>`<li class="${item.complete?'ok':''}">${escapeHTML(item.text)}</li>`).join('');
}
function roadmapSection(section){
  const done=section.items.filter(item=>item.complete).length;
  return `<div class="ry-q"><h4>${escapeHTML(section.title)} <i>${done}/${section.items.length}</i></h4><ul>${roadmapItemList(section.items)}</ul></div>`;
}
function renderSyncedRoadmap(payload){
  const sections=payload.sections||[];
  const undated=sections.find(section=>/^Undated/i.test(section.title));
  const dated=sections.filter(section=>section!==undated);
  if(!undated||!dated.length)return;
  const shipped=undated.items.filter(item=>item.complete);
  const ahead=undated.items.filter(item=>!item.complete);
  const datedDone=dated.reduce((sum,section)=>sum+section.items.filter(item=>item.complete).length,0);
  const datedTotal=dated.reduce((sum,section)=>sum+section.items.length,0);
  const totalDone=datedDone+shipped.length;
  const totalItems=datedTotal+undated.items.length;

  const roadYears=$('#roadYears');
  roadYears.innerHTML=`
    <div class="ry-col">
      <div class="ry-head"><b>Dated milestones</b><span>${datedDone}/${datedTotal} shipped<br>${dated.length} official periods</span></div>
      <div class="ry-qgrid">${dated.map(roadmapSection).join('')}</div>
    </div>
    <div class="ry-col ahead">
      <div class="ry-head"><b>Living roadmap</b><span>${totalDone}/${totalItems} complete<br>${ahead.length} items left</span></div>
      <div class="ry-q"><h4>Undated roadmap · docs order <i>${shipped.length}/${undated.items.length}</i></h4><ul>${roadmapItemList(undated.items)}</ul></div>
      <div class="ry-note">The first unchecked item is marked “up next.” Dates are not inferred: undated items remain undated until Variational publishes a schedule.</div>
    </div>`;

  const pathDated=dated.slice(-4).map(section=>({title:section.title,complete:section.items.every(item=>item.complete),items:section.items}));
  const pendingGroups=[ahead.slice(0,Math.ceil(ahead.length/3)),ahead.slice(Math.ceil(ahead.length/3),Math.ceil(ahead.length*2/3)),ahead.slice(Math.ceil(ahead.length*2/3))].filter(group=>group.length);
  const path=[...pathDated,{title:'Undated · shipped',complete:true,items:shipped},...pendingGroups.map((items,index)=>({title:`Road ahead · ${index+1}`,complete:false,items}))];
  $('#roadStopGrid').innerHTML=path.map((stop,index)=>`<div class="road-stop ${stop.complete?'':'pending'}">
    <span class="road-dot">${stop.complete?'✓':index-pathDated.length}</span>
    <b>${escapeHTML(stop.title)}</b>
    <span>${escapeHTML(stop.items.slice(0,3).map(item=>item.text).join(' · '))}${stop.items.length>3?' · …':''}</span>
  </div>`).join('');
  $('#roadStopGrid').style.gridTemplateColumns=`repeat(${path.length},minmax(0,1fr))`;

  const fetched=new Date(payload.fetchedAt);
  $('#roadSource').innerHTML=`Live synced ${Number.isNaN(fetched.getTime())?'now':fetched.toLocaleString()} · <a href="${escapeHTML(payload.source)}" target="_blank" rel="noopener">Variational Docs Roadmap</a>. ${totalDone}/${totalItems} listed items are checked.`;
}
async function refreshOfficialRoadmap(){
  if(ROADMAP_SYNC_BUSY||location.protocol==='file:')return;
  ROADMAP_SYNC_BUSY=true;
  try{
    const response=await fetch('/api/roadmap',{cache:'no-store'});
    if(!response.ok)throw new Error(`Roadmap API ${response.status}`);
    renderSyncedRoadmap(await response.json());
  }catch(_){
    const source=$('#roadSource');
    if(source)source.innerHTML=`Embedded snapshot · <a href="https://docs.variational.io/getting-started/roadmap" target="_blank" rel="noopener">Variational Docs Roadmap</a>. Live sync is temporarily unavailable.`;
  }finally{ROADMAP_SYNC_BUSY=false;}
}

